USE SCHEMA DEMO_PARALLELS.RAW;

CREATE OR REPLACE TABLE RAW_LICENSES (
    ID            INT AUTOINCREMENT,
    LICENSE_KEY   VARCHAR,
    HWID          VARCHAR,
    EDITION       VARCHAR,
    STATUS        VARCHAR,
    TYPE          VARCHAR,
    ACTIVATED_AT  TIMESTAMP,
    EXPIRES_AT    TIMESTAMP,
    BODY          VARCHAR
);

